import React, { useState } from "react"
import styled from "@emotion/styled"
import { css } from "@emotion/react"
import { colors, MediaQueries } from "../GlobalCSSVariables"
import { withPrefix } from "gatsby"

const photos = [
  { src: "./KCFusionDrillTeam.JPG",  label: "KC Fusion Drill Team",  year: "Past Years", span: "wide" },
  { src: "./DrillTeam2.JPG",         label: "4Eva Envy Drill Team",  year: "Past Years", span: "normal" },
  { src: "./RosiesDanceAcademy.JPG", label: "Rosie's Dance Academy", year: "Past Years", span: "normal" },
  { src: "./Stunt.JPG",              label: "Stunts",                year: "Past Years", span: "normal" },
  { src: "./LiveMusic.JPG",          label: "Live Music",            year: "Past Years", span: "wide" },
  { src: "./JeepClub.JPG",           label: "Jeep Club",             year: "Past Years", span: "normal" },
  { src: "./CorvetteClub.JPG",       label: "Corvette Club",         year: "Past Years", span: "normal" },
  { src: "./marchingband.JPG",       label: "Marching Band",         year: "Past Years", span: "normal" },
  { src: "./foodtruck.JPG",          label: "Food Trucks",           year: "Past Years", span: "normal" },
]

const Wrap = styled.section`
  background-color: ${colors.black};
  padding: 96px 24px 0;

  ${MediaQueries.md} {
    padding: 120px 64px 0;
  }
`

const Header = styled.div`
  max-width: 880px;
  margin: 0 auto 64px;
`

const Eyebrow = styled.p`
  font-family: "Inter", sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: ${colors.red};
  margin: 0 0 18px;
`

const Title = styled.h2`
  font-family: "Playfair Display", "Georgia", serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
  color: ${colors.cream};
  margin: 0 0 20px;
`

const TitleBar = styled.div`
  width: 56px;
  height: 4px;
  background: linear-gradient(90deg, ${colors.red}, ${colors.gold});
`

const Grid = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;

  ${MediaQueries.md} {
    grid-template-columns: repeat(4, 1fr);
  }
`

const Tile = styled.div`
  position: relative;
  overflow: hidden;
  cursor: pointer;
  background-color: ${colors.surface2};

  /* wide items span 2 cols on desktop */
  ${MediaQueries.md} {
    grid-column: ${({ span }) => (span === "wide" ? "span 2" : "span 1")};
  }

  /* Aspect ratio */
  &::before {
    content: "";
    display: block;
    padding-top: ${({ span }) => (span === "wide" ? "52%" : "100%")};

    ${MediaQueries.md} {
      padding-top: ${({ span }) => (span === "wide" ? "56%" : "100%")};
    }
  }

  &:hover img {
    transform: scale(1.06);
  }

  &:hover > div {
    opacity: 1;
  }
`

const TileImg = styled.img`
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.7s cubic-bezier(0.4, 0, 0.2, 1);
`

const TileOverlay = styled.div`
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(13,13,13,0.82) 0%, rgba(13,13,13,0.1) 50%, transparent 100%);
  opacity: 0;
  transition: opacity 0.35s ease;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 20px;

  ${MediaQueries.md} {
    padding: 28px 28px 24px;
  }
`

const TileYear = styled.span`
  font-family: "Inter", sans-serif;
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: ${colors.gold};
  display: block;
  margin-bottom: 6px;
`

const TileLabel = styled.span`
  font-family: "Playfair Display", "Georgia", serif;
  font-size: clamp(0.9rem, 1.5vw, 1.15rem);
  font-weight: 700;
  color: ${colors.white};
  line-height: 1.2;
`

/* Lightbox */
const LightboxBackdrop = styled.div`
  position: fixed;
  inset: 0;
  background: rgba(13,13,13,0.96);
  z-index: 1300;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  cursor: zoom-out;
`

const LightboxImg = styled.img`
  max-width: 90vw;
  max-height: 88vh;
  object-fit: contain;
  display: block;
  cursor: default;
`

const LightboxCaption = styled.div`
  position: absolute;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
`

const LightboxLabel = styled.p`
  font-family: "Playfair Display", "Georgia", serif;
  font-size: 1.1rem;
  font-weight: 700;
  color: ${colors.cream};
  margin: 0;
`

const LightboxClose = styled.button`
  position: absolute;
  top: 20px;
  right: 24px;
  background: none;
  border: none;
  color: ${colors.cream};
  font-size: 1.5rem;
  cursor: pointer;
  padding: 8px 12px;
  font-family: "Inter", sans-serif;
  opacity: 0.6;
  transition: opacity 0.2s ease;
  &:hover { opacity: 1; }
`

const BannerRow = styled.div`
  margin-top: 3px;
  background-color: ${colors.red};
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;

  ${MediaQueries.md} {
    padding: 24px 64px;
  }
`

const BannerText = styled.p`
  font-family: "Inter", sans-serif;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: ${colors.white};
  margin: 0;
  text-align: center;
`

const BannerLink = styled.a`
  font-family: "Inter", sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: ${colors.black};
  background-color: ${colors.gold};
  padding: 10px 20px;
  white-space: nowrap;
  transition: background-color 0.2s ease;
  &:hover { background-color: ${colors.goldMuted}; }
`

const PhotoGrid = () => {
  const [active, setActive] = useState(null)

  return (
    <>
      <Wrap id="gallery">
        <Header>
          <Eyebrow>— Gallery</Eyebrow>
          <Title>Past Parade Events</Title>
          <TitleBar />
        </Header>
        <Grid>
          {photos.map((p, i) => (
            <Tile
              key={i}
              span={p.span}
              onClick={() => setActive(p)}
              role="button"
              aria-label={`View ${p.label}`}
              tabIndex={0}
              onKeyDown={e => e.key === "Enter" && setActive(p)}
            >
              <TileImg
                src={withPrefix(p.src)}
                alt={p.label}
                loading="lazy"
              />
              <TileOverlay>
                <TileYear>{p.year}</TileYear>
                <TileLabel>{p.label}</TileLabel>
              </TileOverlay>
            </Tile>
          ))}
        </Grid>
        <BannerRow>
          <BannerText>Be part of the 2026 Juneteenth Parade — Register by May 31st</BannerText>
          <BannerLink href="./2026Waiver.pdf" target="_blank" rel="noreferrer">
            Get Your Waiver
          </BannerLink>
        </BannerRow>
      </Wrap>

      {active && (
        <LightboxBackdrop onClick={() => setActive(null)}>
          <LightboxClose onClick={() => setActive(null)} aria-label="Close">✕</LightboxClose>
          <LightboxImg
            src={withPrefix(active.src)}
            alt={active.label}
            onClick={e => e.stopPropagation()}
          />
          <LightboxCaption>
            <LightboxLabel>{active.label}</LightboxLabel>
          </LightboxCaption>
        </LightboxBackdrop>
      )}
    </>
  )
}

export default PhotoGrid